const MOBILE_NAV_ITEMS: { id: Screen; label: string; icon: LucideIcon }[] = [
  { id: "dashboard", label: "Pulpit", icon: LayoutDashboard }, { id: "squad", label: "Drużyna", icon: Users },
  { id: "training", label: "Trening", icon: Dumbbell }, { id: "match", label: "Mecz", icon: Play },
];
const NAV_ITEMS: { id: Screen; label: string; icon: LucideIcon }[] = [...MOBILE_NAV_ITEMS, { id: "table", label: "Rozgrywki", icon: Trophy }, { id: "jobs", label: "Rynek pracy", icon: BriefcaseBusiness }, { id: "career", label: "Kariera", icon: BriefcaseBusiness }];

type Go = (screen: Screen) => void;
type GameSetter = Dispatch<SetStateAction<GameState>>;
type GameShellProps = { game: GameState; screen: Screen; go: Go; menuOpen: boolean; setMenuOpen: (open: boolean) => void; saveNow: () => void; savedPulse: boolean; children: ReactNode };
type DashboardProps = { game: GameState; go: Go; resolveDecision: (eventId: string, choiceId: string) => void; prepareMatch: () => void; beginNextSeason: () => void };
type MetricProps = { icon: LucideIcon; label: string; value: string; note: string; tone: string };
type TrainingProps = { game: GameState; setGame: GameSetter; applyTraining: () => void };
type MatchProps = { game: GameState; go: Go; advanceMatch: () => void; prepareMatch: () => void; changeLiveInstruction: (field: "mentality" | "pressing", value: string) => void; resolveMatchMoment?: (momentId: string, choiceId: string) => void };

export function GameShell({ game, screen, go, menuOpen, setMenuOpen, saveNow, savedPulse, children }: GameShellProps) {
  const lastRound = Math.max(1, ...game.fixtures.map((fixture: Fixture) => fixture.round));
  return <div className="game-shell">
    <aside className={`side-nav ${menuOpen ? "open" : ""}`}>
      <div className="side-brand"><span>TT</span><div><strong>TEN TRENER</strong><small>{game.build}</small></div><button className="close-menu" onClick={() => setMenuOpen(false)}><X /></button></div>
      <div className="club-identity"><ClubCrest name={game.club.name} size="large" /><div><strong>{game.employmentStatus === "unemployed" ? "Bez klubu" : game.club.name}</strong><small>{game.employmentStatus === "unemployed" ? "rynek pracy" : `${game.club.competition} • ${game.club.group}`}</small></div></div>
      <nav>{NAV_ITEMS.map((item) => { const Icon = item.icon; return <button key={item.id} className={screen === item.id ? "active" : ""} onClick={() => go(item.id)}><Icon /><span>{item.label}</span></button>; })}</nav>
      <AboutButton /><button className="about-link" onClick={() => go("start")}>Menu główne</button><div className="side-footer"><div><span>Trener</span><strong>{game.coach.name}</strong><small>{game.coach.license} • rep. {game.coach.reputation}</small></div><button onClick={saveNow} title="Zapisz grę"><Save /></button></div>
    </aside>
    {menuOpen && <button className="menu-backdrop" onClick={() => setMenuOpen(false)} aria-label="Zamknij menu" />}
    <div className="game-main"><header className="topbar"><button className="menu-button" onClick={() => setMenuOpen(true)}><Menu /></button><div className="mobile-brand"><span>TEN TRENER</span><small>KARIERA NA TWOICH ZASADACH</small></div><div className="top-metrics"><span><CalendarDays /> {formatDate(game.date)}</span><span>Sezon {game.season}</span><span>Kolejka {Math.min(game.round, lastRound)}</span></div><ThemeButton /><Button variant="outline" size="sm" onClick={saveNow}><Save /> {savedPulse ? "Zapisano" : "Zapisz"}</Button></header><main className="game-content">{children}</main></div>
    <nav className="bottom-nav">{MOBILE_NAV_ITEMS.map((item) => { const Icon = item.icon; return <button key={item.id} className={screen === item.id ? "active" : ""} onClick={() => go(item.id)}><Icon /><span>{item.label}</span></button>; })}<button className={menuOpen ? "active" : ""} onClick={() => setMenuOpen(true)}><MoreHorizontal /><span>Więcej</span></button></nav>
  </div>;
}

export function Dashboard({ game, go, resolveDecision, prepareMatch, beginNextSeason }: DashboardProps) {
  const fixture = currentFixture(game); const home = fixture ? teamForId(game, fixture.home) : undefined; const away = fixture ? teamForId(game, fixture.away) : undefined;
  const position = sortedTable(game.teams).findIndex((team) => team.id === game.club.id) + 1; const unresolved = game.inbox.find((item: { resolved: boolean }) => !item.resolved);
  const [desk, setDesk] = useState<"today" | "opponent" | "club" | "world">("today"); const opponent = fixture ? teamForId(game, fixture.home === game.club.id ? fixture.away : fixture.home) : undefined; const dossier = opponent ? opponentDossier(game, opponent) : undefined;
  return <div className="page-stack dashboard-window">
    <section className="page-heading compact-heading"><div><p className="eyebrow">SERWIS TRENERA • {formatDate(game.date)}</p><h1>{game.coach.name.split(" ")[0]}, decyzja należy do ciebie.</h1><p>{game.club.name} • {position}. miejsce • {TEAM_PLANS[game.teamPlan]?.label ?? "Najsilniejsza XI"}.</p></div><Badge className="status-badge"><span className="live-dot" /> zapis aktywny</Badge></section>

    <BoardGoalPanel game={game} />
    {game.newSeasonPending ? <section className="season-end hero-card"><div><Trophy /><span>KONIEC SEZONU</span></div><h2>{position}. miejsce w lidze</h2><p>Świat gry zakończył rozgrywki. Ruchy ligowe zostaną zastosowane według reguł tej edycji.</p><Button size="lg" onClick={beginNextSeason}>Rozlicz sezon <ChevronRight /></Button></section> : fixture && <section className="next-match hero-card compact-match-card"><div className="match-kicker"><span>K{game.round} • {fixture.home === game.club.id ? "DOM" : "WYJAZD"}</span><span>{formatDate(fixture.date)}</span></div><div className="versus"><div><span className="club-crest">{initials(home?.name ?? "")}</span><strong>{home?.name}</strong></div><span>VS</span><div><span className="club-crest away">{initials(away?.name ?? "")}</span><strong>{away?.name}</strong></div></div><div className="match-actions"><div><small>Gotowość</small><Progress value={game.training.readiness} /><strong>{game.training.readiness}%</strong></div><Button size="lg" onClick={prepareMatch}>{game.training.completedRound === game.round ? "Do meczu" : "Ułóż mikrocykl"} <Play /></Button></div></section>}
    <nav className="desk-tabs" aria-label="Sekcje pulpitu"><button className={desk === "today" ? "active" : ""} onClick={() => setDesk("today")}><b>01</b><span>Dzisiaj</span></button><button className={desk === "opponent" ? "active" : ""} onClick={() => setDesk("opponent")}><b>02</b><span>Rywal</span></button><button className={desk === "club" ? "active" : ""} onClick={() => setDesk("club")}><b>03</b><span>Klub</span></button><button className={desk === "world" ? "active" : ""} onClick={() => setDesk("world")}><b>04</b><span>Polska</span></button></nav>
    <div className="desk-window" key={desk}>
      {desk === "today" && <TrainingWeekResult game={game} />}{desk === "today" && <div className="dashboard-columns dashboard-today">{game.lastDecisionOutcome && <section className="panel decision-feedback"><div className="panel-title"><div><BadgeCheck /><span>Skutek ostatniej decyzji</span></div><small>rozliczone</small></div><h3>{game.lastDecisionOutcome.title}</h3><p><b>{game.lastDecisionOutcome.choice}</b> — {game.lastDecisionOutcome.feedback}</p><div>{game.lastDecisionOutcome.changes.map((change) => <span key={change}>{change}</span>)}</div></section>}<section className="panel"><div className="panel-title"><div><ClipboardList /><span>Skrzynka i decyzje</span></div><Badge variant="outline">{game.inbox.filter((item: { resolved: boolean }) => !item.resolved).length} nowe</Badge></div>{unresolved ? <div className="decision-card"><small>{unresolved.category.toUpperCase()} • WYMAGA DECYZJI</small>{unresolved.story && <span className="story-episode">SPRAWA W TOKU • CZĘŚĆ {unresolved.story.step+1} Z 3</span>}<h3>{unresolved.title}</h3><p>{unresolved.body}</p><div className="decision-actions">{unresolved.choices.map((choice) => <Button variant="outline" disabled={Boolean(game.matchState && !game.matchState.completed)} key={choice.id} onClick={() => resolveDecision(unresolved.id, choice.id)}><span>{choice.label}</span><small>{previewIssueEffects(choice.effects).join(" • ") || "skutek może wrócić później"}</small></Button>)}</div><p className="consequence-note"><CircleAlert /> {game.matchState && !game.matchState.completed ? "Mecz trwa — sprawy klubowe rozpatrzysz po ostatnim gwizdku." : "Znasz kierunek, lecz dokładna skala zostanie wylosowana i zapisana."}</p></div> : <div className="empty-state compact"><BadgeCheck /><strong>Brak pilnych spraw</strong><span>Dziś można po prostu trenować.</span></div>}</section><section className="panel compact-goals"><div className="panel-title"><div><Target /><span>Cele rozwojowe</span></div><small>zima / koniec</small></div><div className="goal-progress-list">{game.developmentGoals.map((goal: DevelopmentGoal) => <div key={goal.id}><div><strong>{goal.label}</strong></div><small className="development-detail">{goalProgressText(goal, game.seasonEvidence)}</small><Progress value={goalProgressPercent(goal, game.seasonEvidence)} /></div>)}</div><button className="text-action" onClick={() => go("career")}>Otwórz profil <ChevronRight /></button></section></div>}
      {desk === "opponent" && dossier && <section className="panel opponent-dossier"><div className="panel-title"><div><Target /><span>Rywal pod lupą: {opponent?.name}</span></div><small>dane gry</small></div><div className="dossier-grid">{dossier.facts.map((fact) => <span key={fact.label}><small>{fact.label}</small><b>{fact.value}</b></span>)}</div><p><b>ZALECENIE SZTABU: {dossier.recommendation}</b></p><p>{dossier.reason}</p><p className="source-note">Źródło: aktualny stan drużyny i wyniki ligowe w grze.</p><button className="text-action" onClick={() => go("squad")}>Dopasuj plan drużyny <ChevronRight /></button></section>}
      {desk === "club" && <div className="club-desk"><section className="metric-grid"><Metric icon={Trophy} label="Pozycja" value={`${position}.`} note={`${game.teams.length} drużyn`} tone="green" /><Metric icon={Gauge} label="Presja zarządu" value={`${game.pressures.board}%`} note={pressureLabel(game.pressures.board)} tone={game.pressures.board > 60 ? "red" : "amber"} /><Metric icon={Flame} label="Wypalenie trenera" value={`${game.burnout}%`} note={`${burnoutLabel(game.burnout)} • ${signed(game.lastBurnoutChange)} w tyg.`} tone={game.burnout > 60 ? "red" : "blue"} /><Metric icon={Zap} label="Energia" value={`${game.coach.skills.energy}`} note={game.coach.profile} tone="violet" /></section><section className="panel world-environment"><div className="panel-title"><div><Shield /><span>Środowisko: {game.environment.label}</span></div><small>{game.environment.status}</small></div><p>{game.environment.work}</p><div><span><b>{game.environment.trainingSessions}</b> sesje / tydzień</span><span><b>{game.environment.readinessCap}%</b> limit gotowości</span><span><b>{game.worldHumor < 40 ? "powściągliwy" : game.worldHumor < 70 ? "żywy" : "barwny"}</b> ton świata</span><span><b>×{game.careerChallenge.pressureMultiplier.toFixed(2)}</b> presja licencji</span></div></section><section className="panel burnout-explainer"><div><Flame /><strong>Wypalenie dotyczy trenera, nie piłkarzy.</strong></div><p>Rośnie przez presję, kryzysy i forsowanie pracy. Od 36% zwiększa ryzyko błędów przygotowania; odpoczynek i spokojniejszy rytm mogą je obniżyć.</p><div className="burnout-scale"><span>0–24 niskie</span><span>25–44 rosnące</span><span>45–64 wysokie</span><span>65+ krytyczne</span></div></section></div>}
      {desk === "world" && <section className="panel world-pulse"><div className="panel-title"><div><Globe2 /><span>Reszta Polski gra w tle</span></div><small>{formatDate(game.worldActivity.date)}</small></div><div className="world-pulse-metrics"><span><b>{game.worldActivity.competitionsAdvanced}</b> rozgrywek ruszyło</span><span><b>{game.worldActivity.matchesPlayed}</b> meczów AI</span><span><b>{game.worldActivity.squadMoves ?? 0}</b> ruchów kadrowych</span><span><b>{game.worldActivity.managerChanges}</b> zmian trenerów</span></div>{game.worldActivity.headlines.length ? <div className="world-headlines">{game.worldActivity.headlines.map((headline) => <p key={headline}>{headline}</p>)}</div> : <p className="source-note">Pierwsze wyniki świata pojawią się po rozegraniu kolejki.</p>}<button className="text-action" onClick={() => go("table")}>Otwórz wszystkie rozgrywki <ChevronRight /></button></section>}
    </div>
  </div>;
}

export function DashboardV14(props: DashboardProps) {
  const { game, go } = props;
  if (!game.careerEnded && game.employmentStatus === "employed") return <Dashboard {...props} />;
  const retired = game.careerEnded || game.employmentStatus === "retired";
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">{retired ? "KRONIKA ZAMKNIĘTA" : "KARUZELA TRENERSKA"}</p><h1>{retired ? "Kariera zakończona" : "Czas na nową ławkę"}</h1><p>{retired ? "Save pozostaje pełnym zapisem drogi trenera." : "Zwolnienie nie kończy kariery. Licencja i reputacja wyznaczają realny rynek."}</p></div></section><section className="season-end hero-card"><div><BriefcaseBusiness /><span>{retired ? "EMERYTURA" : "BEZROBOCIE"}</span></div><h2>{game.coach.name}</h2><p>{game.careerStats.seasons} sezonów • {game.careerStats.matches} meczów • {game.careerStats.promotions} awansów</p><Button size="lg" onClick={() => go(retired ? "career" : "jobs")}>{retired ? "Zobacz podsumowanie" : "Otwórz rynek pracy"} <ChevronRight /></Button></section></div>;
}

function Metric({ icon: Icon, label, value, note, tone }: MetricProps) { return <article className={`metric ${tone}`}><Icon /><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></article>; }

export function Squad({ game, setGame }: { game: GameState; setGame: GameSetter }) {
  const slots = FORMATIONS[game.tactic.formation]; const starters = new Set(Object.values(game.tactic.assignments));
  const policy = POLICY_EFFECTS[game.squadPolicy] ?? POLICY_EFFECTS.BALANCED;
  const bestEleven = () => setGame({ ...game, tactic: { ...game.tactic, assignments: selectBestLineup(game.players, slots) } });
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">PIERWSZY ZESPÓŁ</p><h1>Kadra i kondycja</h1><p>{game.players.length} zawodników. Jakość jest stała w sezonie; dyspozycja reaguje na formę, morale i zmęczenie; ocena meczowa dolicza pozycję.</p></div><Button onClick={bestEleven}><Sparkles /> Najlepsza XI pozycyjna</Button></section><section className="panel squad-legend"><div><Activity /><strong>Kondycja określa świeżość zawodnika.</strong></div><p>Spadek kondycji obniża możliwości; poniżej 60% koszt sportowy i ryzyko urazu są duże. „Najlepsza XI” najpierw dopasowuje pozycje, potem porównuje dyspozycję i nigdy nie wybiera kontuzjowanego zawodnika.</p></section><section className="policy-panel"><span>Polityka prowadzenia kadry</span><div className="policy-row">{Object.entries(POLICY_EFFECTS).map(([id, effect]) => <button className={game.squadPolicy === id ? "active" : ""} key={id} onClick={() => setGame({ ...game, squadPolicy: id })}><strong>{effect.label}</strong></button>)}</div><div className="policy-explainer"><b>{policy.label}</b><span>{policy.short}</span><small>Siła meczu {signed(policy.matchStrength)} • zmęczenie XI {signed(policy.fatigue)} • morale XI {signed(policy.morale)} • wypalenie trenera {signed(policy.burnout)} / tydzień</small></div></section><section className="roster-cards">{[...game.players].sort((a, b) => Number(starters.has(b.id)) - Number(starters.has(a.id)) || POSITIONS.indexOf(a.primary) - POSITIONS.indexOf(b.primary)).map((player) => { const assignedSlot = slots.find((slot) => game.tactic.assignments[slot] === player.id); const penalty = assignedSlot ? positionPenalty(player, assignedSlot) : 0; const breakdown = liveBreakdown(player); const condition = conditionFromFatigue(player.fatigue); const injured = (player.injuryWeeks ?? 0) > 0; return <article className={`player-card ${starters.has(player.id) ? "starter" : ""} ${injured ? "injured" : ""}`} key={player.id}><header><div><strong>{player.name}</strong><small>{player.age} lat • {player.personality} • {player.status}</small></div><Badge variant="outline">{assignedSlot ?? player.primary}{starters.has(player.id) ? " • XI" : ""}</Badge></header><div className="player-rating-strip"><span><small>JAKOŚĆ</small><b>{player.baseOVR}</b></span><span><small>DYSPOZYCJA</small><b className={liveOVR(player) < player.baseOVR ? "bad" : "live"}>{liveOVR(player)}</b></span><span><small>W MECZU</small><b className={penalty >= 0.15 || injured ? "bad" : "effective"}>{assignedSlot ? effectiveOVR(player, assignedSlot) : "—"}</b></span><span><small>MORALE</small><b>{player.morale}</b></span></div><div className="condition-line"><div><span>Kondycja</span><strong>{condition}% • {conditionStatus(condition)}</strong></div><Progress value={condition} /></div>{injured && <p className="injury-warning"><CircleAlert /> Kontuzja: przerwa jeszcze {player.injuryWeeks} tyg.</p>}{penalty > 0 && <p className="position-warning"><CircleAlert /> Gra na tej pozycji obniża ocenę meczową o {Math.round(penalty * 100)}%.</p>}<small className="live-note">{conditionAdvice(condition, game.club.tier)}</small></article>; })}</section></div>;
}

export function Tactics({ game, setGame }: { game: GameState; setGame: GameSetter }) {
  const slots = FORMATIONS[game.tactic.formation];
  const updateFormation = (formation: keyof typeof FORMATIONS) => setGame({ ...game, tactic: { ...game.tactic, formation, assignments: selectBestLineup(game.players, FORMATIONS[formation]) } });
  const setTactic = (key: keyof Tactic, value: unknown) => setGame({ ...game, tactic: { ...game.tactic, [key]: value } });
  const assignPlayer = (slot: string, playerId: string) => { const assignments = { ...game.tactic.assignments }; const oldPlayer = assignments[slot]; const previousSlot = slots.find((other) => other !== slot && assignments[other] === playerId); assignments[slot] = playerId; if (previousSlot) { if (oldPlayer) assignments[previousSlot] = oldPlayer; else delete assignments[previousSlot]; } setTactic("assignments", assignments); };
  const average = Math.round(slots.reduce((sum, slot) => { const player = game.players.find((item) => item.id === game.tactic.assignments[slot]); return sum + (player ? effectiveOVR(player, slot) : 0); }, 0) / 11);
  const controls: [keyof Tactic, string, string[]][] = [["mentality", "Mentalność", ["Defensywna", "Zrównoważona", "Ofensywna"]], ["tempo", "Tempo", ["Niskie", "Normalne", "Wysokie"]], ["pressing", "Pressing", ["Niski", "Średni", "Wysoki"]], ["line", "Linia obrony", ["Niska", "Średnia", "Wysoka"]], ["width", "Szerokość", ["Wąska", "Standardowa", "Szeroka"]], ["buildUp", "Rozegranie", ["Krótkie", "Mieszane", "Bezpośrednie"]], ["passingRisk", "Ryzyko podań", ["Bezpieczne", "Umiarkowane", "Odważne"]]];
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">PLAN MECZU</p><h1>Taktyka i wyjściowa XI</h1><p>Pozycja, forma, kondycja i urazy składają się na realną siłę ustawienia.</p></div><div className="lineup-score"><span>Ocena XI</span><strong>{average}</strong></div></section><section className="tactics-layout"><div className="pitch-panel"><div className="pitch"><div className="halfway" /><div className="center-circle" /><div className="box top" /><div className="box bottom" /><div className="formation-grid">{slots.map((slot, index) => { const player = game.players.find((item) => item.id === game.tactic.assignments[slot]); const penalty = player ? positionPenalty(player, slot) : 0; const coords = FORMATION_COORDS[game.tactic.formation][index]; return <div className={`pitch-player ${penalty > 0 || (player?.injuryWeeks ?? 0) > 0 ? "mismatch" : ""}`} style={{ left: `${coords.left}%`, top: `${coords.top}%` }} key={`${game.tactic.formation}-${slot}-${index}`}><span>{player ? effectiveOVR(player, slot) : "—"}</span><strong>{slot}</strong><small>{player?.name.split(" ").at(-1)}</small></div>; })}</div></div><div className="formation-picker">{Object.keys(FORMATIONS).map((formation) => <button key={formation} className={game.tactic.formation === formation ? "active" : ""} onClick={() => updateFormation(formation as keyof typeof FORMATIONS)}>{formation}</button>)}</div></div><div className="panel tactic-controls"><div className="panel-title"><div><SlidersHorizontal /><span>Instrukcje</span></div></div>{controls.map(([key, label, options]) => <label className="field compact" key={key}><span>{label}</span><NativeSelect value={String(game.tactic[key])} onChange={(event) => setTactic(key, event.target.value)} className="w-full">{options.map((option) => <NativeSelectOption key={option}>{option}</NativeSelectOption>)}</NativeSelect></label>)}</div></section><section className="panel lineup-editor"><div className="panel-title"><div><Users /><span>Obsada pozycji</span></div><small>pozycja → dyspozycja → kondycja</small></div><div className="assignment-grid">{slots.map((slot) => { const current = game.players.find((player) => player.id === game.tactic.assignments[slot]); const penalty = current ? positionPenalty(current, slot) : 0; return <label className={`assignment ${penalty > 0 || (current?.injuryWeeks ?? 0) > 0 ? "warning" : ""}`} key={slot}><span><b>{slot}</b>{penalty > 0 && <small>kara −{Math.round(penalty * 100)}%</small>}{(current?.injuryWeeks ?? 0) > 0 && <small>zawodnik kontuzjowany</small>}</span><NativeSelect value={game.tactic.assignments[slot] ?? ""} onChange={(event) => assignPlayer(slot, event.target.value)} className="w-full">{[...game.players].sort((a, b) => Number((a.injuryWeeks ?? 0) > 0) - Number((b.injuryWeeks ?? 0) > 0) || positionPenalty(a, slot) - positionPenalty(b, slot) || liveOVR(b) - liveOVR(a)).map((player) => <NativeSelectOption disabled={(player.injuryWeeks ?? 0) > 0} key={player.id} value={player.id}>{player.name} • {player.primary} • {player.injuryWeeks ? `URAZ ${player.injuryWeeks} tyg.` : `ocena ${effectiveOVR(player, slot)} • kond. ${100 - player.fatigue}%`}</NativeSelectOption>)}</NativeSelect></label>; })}</div></section></div>;
}

export function Training({ game, setGame, applyTraining }: TrainingProps) {
  const locked = game.training.completedRound === game.round; const fixture = currentFixture(game); const opponentId = fixture?.home === game.club.id ? fixture.away : fixture?.home; const opponent = opponentId ? teamForId(game, opponentId) : undefined; const policy = POLICY_EFFECTS[game.squadPolicy] ?? POLICY_EFFECTS.BALANCED;
  const projection=projectTraining(game); const {effect,recovery:passiveRecovery}=projection;
  const predictedCondition=locked?trainingMetrics(game.players,game.tactic,game.training.readiness).condition:projection.after.condition;
  const updateSession = (index: number, key: "focus" | "intensity", value: TrainingFocus | TrainingIntensity) => {
    const sessions = game.training.sessions.map((session, sessionIndex) => {
      if (sessionIndex !== index) return session;
      if (key === "focus") return { ...session, focus: value as TrainingFocus, intensity: value === "Regeneracja" && session.intensity === "Wysoka" ? "Niska" as TrainingIntensity : session.intensity };
      return { ...session, intensity: value as TrainingIntensity };
    });
    setGame({ ...game, training: { ...game.training, sessions, preset: "CUSTOM" } });
  };
  const choosePreset = (preset: string) => setGame({ ...game, training: { ...game.training, preset, sessions: trainingPresetSessions(game.environment.trainingSessions, preset) } });
  const focuses: TrainingFocus[] = ["Regeneracja", "Analiza rywala", "Motoryka", "Taktyka", "Finalizacja", "Pressing", "Atmosfera", "Rozwój młodych", "Stałe fragmenty"];
  const intensities: TrainingIntensity[] = ["Niska", "Normalna", "Wysoka"];
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">MIKROCYKL • KOLEJKA {game.round}</p><h1>Wybierz plan tygodnia</h1><p>{game.environment.label}: sztab rozpisze wszystkie {game.training.sessions.length} sesji. Szczegóły możesz sprawdzić, ale nie musisz klikać każdego dnia osobno.</p></div><div className="lineup-score"><span>{locked ? "Kondycja XI" : "Prognoza automatycznej XI"}</span><strong>{predictedCondition}%</strong></div></section><section className={`match-week panel ${locked ? "locked" : ""}`}><div><CalendarDays /><span><small>NAJBLIŻSZY MECZ</small><strong>{opponent?.name ?? "brak rywala"} • {fixture?.home === game.club.id ? "dom" : "wyjazd"}</strong></span></div><Badge variant="outline">{locked ? "mikrocykl wykonany" : `${game.training.sessions.length} sesji w planie`}</Badge></section>{locked ? <TrainingWeekResult game={game} /> : <TrainingWeekChoices game={game} choose={choosePreset} />}<section className="training-preset-grid">{Object.entries(TRAINING_PRESETS).map(([id, preset]) => <button disabled={locked} key={id} className={`training-preset ${game.training.preset === id ? "active" : ""}`} onClick={() => choosePreset(id)}><strong>{preset.label}</strong><span>{preset.description}</span></button>)}</section><section className="training-grid"><div className="panel session-plan"><div className="panel-title"><div><Target /><span>{chosenTrainingLabel(game)} • {game.training.sessions.length} sesji</span></div><small>plan całego tygodnia</small></div><div className="microcycle-days">{game.training.sessions.map((session, index) => <span key={session.id}><b>{index + 1}. {session.day}</b><small>{session.focus} • {session.intensity.toLowerCase()}</small></span>)}</div><details className="advanced-microcycle"><summary>Dostosuj pojedyncze sesje</summary><div className="session-plan-list">{game.training.sessions.map((session, index) => <article className="training-session-card" key={session.id}><header><span><b>SESJA {index + 1}</b><strong>{session.day}</strong></span><small>{trainingFocusNote(session.focus as TrainingFocus)}</small></header><label className="field compact"><span>Akcent</span><NativeSelect disabled={locked} value={session.focus} onChange={(event) => updateSession(index, "focus", event.target.value as TrainingFocus)} className="w-full">{focuses.map((focus) => <NativeSelectOption key={focus}>{focus}</NativeSelectOption>)}</NativeSelect></label><div><span className="control-label">Intensywność</span><div className="intensity-options">{intensities.map((value) => <button disabled={locked || (session.focus === "Regeneracja" && value === "Wysoka")} className={session.intensity === value ? "active" : ""} key={value} onClick={() => updateSession(index, "intensity", value)}>{value}</button>)}</div></div></article>)}</div></details></div><aside className="panel microcycle-summary"><div className="panel-title"><div><Gauge /><span>Skutek całego tygodnia</span></div></div><div className="risk-preview"><div><span>Naturalna regeneracja</span><strong>+{passiveRecovery} p.p. kondycji</strong></div><div><span>Wpływ mikrocyklu na kondycję</span><strong>{effect.fatigueDelta > 0 ? "−" : "+"}{Math.abs(effect.fatigueDelta)} p.p.</strong></div><div><span>{locked ? "Aktualna kondycja XI" : "Prognoza automatycznej XI"}</span><strong>{predictedCondition}%</strong></div><div><span>Przewidywana gotowość</span><strong>{locked ? game.training.readiness : projection.after.readiness}%</strong></div><div><span>Morale / forma</span><strong>{effect.moraleDelta >= 0 ? "+" : ""}{effect.moraleDelta} / {effect.formDelta >= 0 ? "+" : ""}{effect.formDelta}</strong></div><div><span>Plan drużyny</span><strong>{TEAM_PLANS[game.teamPlan]?.label ?? TEAM_PLANS.STRONGEST.label}</strong></div><div><span>Ryzyko przeciążenia</span><strong>{effect.risk}</strong></div></div><p className="training-advice">Kondycja odbudowuje się przez dni między meczami, a potem zmienia ją wybrany mikrocykl. Jedną XI można forsować, ale koszt będzie narastał.</p><Button disabled={locked} className="w-full" size="lg" onClick={applyTraining}>{locked ? "Mikrocykl już wykonany" : `Zrealizuj cały mikrocykl`} {!locked && <ChevronRight />}</Button></aside></section></div>;
}

function trainingFocusNote(focus: TrainingFocus) {
  if (focus === "Regeneracja") return "świeżość i zejście z obciążeń";
  if (focus === "Analiza rywala" || focus === "Taktyka" || focus === "Stałe fragmenty") return "przygotowanie meczowe";
  if (focus === "Atmosfera") return "morale i relacje";
  if (focus === "Rozwój młodych") return "bodziec głównie dla U21";
  if (focus === "Motoryka" || focus === "Pressing") return "większy koszt fizyczny";
  return "forma sytuacyjna";
}

export function MatchLegacy({ game, go, advanceMatch, prepareMatch, changeLiveInstruction }: MatchProps) {
  const match = game.matchState as MatchState | undefined; const fixture = match?.fixture ?? currentFixture(game);
  if (!fixture) return <div className="page-stack"><section className="empty-state panel"><Trophy /><strong>Brak meczu w tej kolejce</strong><Button onClick={() => go("dashboard")}>Wróć do pulpitu</Button></section></div>;
  const home = teamForId(game, fixture.home); const away = teamForId(game, fixture.away);
  const startingPlayers = Object.values(game.tactic.assignments).map((id) => game.players.find((player) => player.id === id)).filter(Boolean);
  const averageCondition = startingPlayers.length ? Math.round(startingPlayers.reduce((sum, player) => sum + (100 - (player?.fatigue ?? 0)), 0) / startingPlayers.length) : 0;
  if (!match) return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">DZIEŃ MECZOWY</p><h1>{home?.name} — {away?.name}</h1><p>Kolejka {game.round}. Skład i taktyka są gotowe do zatwierdzenia.</p></div></section><section className="match-ready hero-card"><div className="versus"><div><span className="club-crest large">{initials(home?.name ?? "")}</span><strong>{home?.name}</strong><small>OVR {home?.ovr}</small></div><span>VS</span><div><span className="club-crest large away">{initials(away?.name ?? "")}</span><strong>{away?.name}</strong><small>OVR {away?.ovr}</small></div></div><div className="pre-match-facts"><span>Formacja <b>{game.tactic.formation}</b></span><span>Gotowość <b>{game.training.readiness}%</b></span><span>Kondycja XI <b>{averageCondition}%</b></span><span>Presja <b>{pressureLabel(Math.max(...Object.values(game.pressures) as number[]))}</b></span>{game.burnout > 35 && <span>Wypalenie <b>{game.burnout}% obniża przygotowanie</b></span>}</div><Button className="primary-cta" size="lg" onClick={prepareMatch}><Play /> Rozpocznij mecz</Button></section></div>;
  const visibleEvents = match.plannedEvents.filter((event) => event.minute <= match.minute); const visibleHome = visibleEvents.filter((event) => event.kind === "goal" && event.side === "home").length; const visibleAway = visibleEvents.filter((event) => event.kind === "goal" && event.side === "away").length;
  return <div className="page-stack match-page"><section className="live-score"><div className="live-top"><span className="live-pill"><span className="live-dot" /> {match.completed ? "KONIEC" : "NA ŻYWO"}</span><span>{match.minute}&apos;</span></div><div className="scoreboard"><div><span className="club-crest">{initials(home?.name ?? "")}</span><strong>{home?.name}</strong></div><b>{visibleHome}<span>:</span>{visibleAway}</b><div><span className="club-crest away">{initials(away?.name ?? "")}</span><strong>{away?.name}</strong></div></div><div className="minute-bar"><span style={{ width: `${match.minute / 0.9}%` }} /></div></section><div className="match-columns"><section className="panel timeline"><div className="panel-title"><div><Play /><span>Przebieg meczu</span></div></div><div className="events">{visibleEvents.length ? [...visibleEvents].reverse().map((event, index) => <article className={event.kind} key={`${event.minute}-${index}`}><b>{event.minute}&apos;</b><span>{event.text}</span></article>) : <div className="empty-state compact"><span>Gwiazdek jeszcze nie ma. Jest walka o drugi kontakt.</span></div>}</div>{!match.completed ? <Button className="w-full" size="lg" onClick={advanceMatch}>Następne 15 minut <ChevronRight /></Button> : <Button className="w-full" size="lg" onClick={() => go("dashboard")}>Analiza i pulpit <ChevronRight /></Button>}</section><aside className="panel live-controls"><div className="panel-title"><div><SlidersHorizontal /><span>Decyzje w trakcie</span></div></div><label className="field compact"><span>Mentalność</span><NativeSelect disabled={match.completed || !!match.activeMomentId || match.lastInstructionMinute === match.minute} value={game.tactic.mentality} onChange={(event) => changeLiveInstruction("mentality", event.target.value)} className="w-full"><NativeSelectOption>Defensywna</NativeSelectOption><NativeSelectOption>Zrównoważona</NativeSelectOption><NativeSelectOption>Ofensywna</NativeSelectOption></NativeSelect><small>{mentalityAdvice(match, game.club.id, game.tactic.mentality)}</small></label><label className="field compact"><span>Pressing</span><NativeSelect disabled={match.completed || !!match.activeMomentId || match.lastInstructionMinute === match.minute} value={game.tactic.pressing} onChange={(event) => changeLiveInstruction("pressing", event.target.value)} className="w-full"><NativeSelectOption>Niski</NativeSelectOption><NativeSelectOption>Średni</NativeSelectOption><NativeSelectOption>Wysoki</NativeSelectOption><NativeSelectOption>Bardzo wysoki</NativeSelectOption></NativeSelect><small>{pressingAdvice(game.tactic.pressing, lineupCondition(game.players, game.tactic.assignments), accruePressing(match.pressingExposure, game.tactic.pressing, match.minute))}</small></label><p className="analysis-hint"><Target /> Cel „Analiza”: wykonaj sesję analizy rywala w tygodniu i podejmij decyzję z ławki po 30. minucie. Wynik nie warunkuje postępu.</p><div className="match-stats"><h3>Statystyki</h3><Stat label="Posiadanie" home={`${match.possessionHome}%`} away={`${100 - match.possessionHome}%`} /><Stat label="Strzały" home={String(visibleEvents.filter(e => e.side === "home" && ["goal","chance"].includes(e.kind)).length)} away={String(visibleEvents.filter(e => e.side === "away" && ["goal","chance"].includes(e.kind)).length)} /><Stat label="Żółte kartki" home={String(visibleEvents.filter((event) => event.side === "home" && event.kind === "card").length)} away={String(visibleEvents.filter((event) => event.side === "away" && event.kind === "card").length)} /></div><p className="consequence-note"><CircleAlert /> Ofensywna gra zwiększa presję osobistą. Koszt fizyczny wynika z pressingu i tempa.</p></aside></div></div>;
}

export function Match({ game, go, advanceMatch, prepareMatch, changeLiveInstruction, resolveMatchMoment }: MatchProps) {
  const match = game.matchState as MatchState | undefined;
  const fixture = match?.fixture ?? currentFixture(game);
  if (!fixture) return <div className="page-stack"><section className="empty-state panel"><Trophy /><strong>Brak meczu w tej kolejce</strong><Button onClick={() => go("dashboard")}>Wróć do pulpitu</Button></section></div>;
  const home = teamForId(game, fixture.home); const away = teamForId(game, fixture.away);
  const startingPlayers = Object.values(game.tactic.assignments).map((id) => game.players.find((player) => player.id === id)).filter(Boolean);
  const averageCondition = startingPlayers.length ? Math.round(startingPlayers.reduce((sum, player) => sum + (100 - (player?.fatigue ?? 0)), 0) / startingPlayers.length) : 0;
  if (!match) return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">DZIEŃ MECZOWY</p><h1>{home?.name} — {away?.name}</h1><p>Kolejka {game.round}. Sztab zamknął skład i plan.</p></div></section><section className="match-ready hero-card"><div className="versus"><div><ClubCrest name={home?.name ?? ""} size="large" /><strong>{home?.name}</strong><small>OVR {home?.ovr}</small></div><span>VS</span><div><ClubCrest name={away?.name ?? ""} size="large" muted /><strong>{away?.name}</strong><small>OVR {away?.ovr}</small></div></div><div className="pre-match-facts"><span>Plan <b>{TEAM_PLANS[game.teamPlan]?.label ?? game.tactic.formation}</b></span><span>Gotowość <b>{game.training.readiness}%</b></span><span>Kondycja XI <b>{averageCondition}%</b></span><span>Presja <b>{pressureLabel(Math.max(...Object.values(game.pressures) as number[]))}</b></span></div><Button className="primary-cta" size="lg" onClick={prepareMatch}><Play /> Rozpocznij mecz</Button></section></div>;
  const visibleEvents = match.plannedEvents.filter((event) => event.minute <= match.minute);
  const visibleHome = visibleEvents.filter((event) => event.kind === "goal" && event.side === "home").length; const visibleAway = visibleEvents.filter((event) => event.kind === "goal" && event.side === "away").length;
  const activeMoment = match.coachMoments?.find((item) => item.id === match.activeMomentId);
  return <div className="page-stack match-page">
    <section className="live-score match-scoreboard"><div className="live-top"><span className="live-pill"><span className="live-dot" /> {match.completed ? "KONIEC" : "NA ŻYWO"}</span><span>{match.minute}&apos;</span></div><div className="scoreboard"><div><ClubCrest name={home?.name ?? ""} /><strong>{home?.name}</strong></div><b>{visibleHome}<span>:</span>{visibleAway}</b><div><ClubCrest name={away?.name ?? ""} muted /><strong>{away?.name}</strong></div></div><div className="minute-bar"><span style={{ width: `${match.minute / 0.9}%` }} /></div></section>
    <div className="match-columns match-control-room"><section className="panel timeline"><div className="panel-title"><div><Play /><span>Przebieg meczu</span></div><small>{visibleEvents.length} zdarzeń</small></div><div className="events" aria-live="polite">{visibleEvents.length ? [...visibleEvents].reverse().map((event, index) => <article className={event.kind} key={`${event.minute}-${index}`}><b>{event.minute}&apos;</b><span>{event.text}</span></article>) : <div className="empty-state compact"><span>Gwiazdek jeszcze nie ma. Jest walka o drugi kontakt.</span></div>}</div>
      {activeMoment && <section className="coach-moment" aria-live="assertive"><small>REAKCJA TRENERA • {activeMoment.minute}&apos;</small><h3>{activeMoment.title}</h3><p>{activeMoment.body}</p><div>{activeMoment.choices.map((choice) => <button key={choice.id} onClick={() => resolveMatchMoment?.(activeMoment.id, choice.id)}><b>{choice.label}</b><span>{choice.preview}</span><small>Możliwy efekt: siła około {choice.strength >= 0 ? "+" : ""}{choice.strength}; zmęczenie {choice.fatigue >= 0 ? "+" : ""}{choice.fatigue}</small></button>)}</div></section>}
      <div className="match-action-dock"><span><b>{visibleHome}:{visibleAway}</b> • {match.minute}&apos;</span>{activeMoment ? <strong>Wybierz reakcję</strong> : !match.completed ? <Button size="lg" onClick={advanceMatch}>Następne 15 minut <ChevronRight /></Button> : <Button size="lg" onClick={() => go("dashboard")}>Raport i pulpit <ChevronRight /></Button>}</div></section>
      <aside className="panel live-controls"><div className="panel-title"><div><SlidersHorizontal /><span>Decyzje w trakcie</span></div></div><label className="field compact"><span>Mentalność</span><NativeSelect disabled={match.completed || Boolean(activeMoment) || match.lastInstructionMinute === match.minute} value={game.tactic.mentality} onChange={(event) => changeLiveInstruction("mentality", event.target.value)} className="w-full"><NativeSelectOption>Defensywna</NativeSelectOption><NativeSelectOption>Zrównoważona</NativeSelectOption><NativeSelectOption>Ofensywna</NativeSelectOption></NativeSelect><small>{mentalityAdvice(match, game.club.id, game.tactic.mentality)}</small></label><label className="field compact"><span>Pressing</span><NativeSelect disabled={match.completed || Boolean(activeMoment) || match.lastInstructionMinute === match.minute} value={game.tactic.pressing} onChange={(event) => changeLiveInstruction("pressing", event.target.value)} className="w-full"><NativeSelectOption>Niski</NativeSelectOption><NativeSelectOption>Średni</NativeSelectOption><NativeSelectOption>Wysoki</NativeSelectOption><NativeSelectOption>Bardzo wysoki</NativeSelectOption></NativeSelect><small>{pressingAdvice(game.tactic.pressing, lineupCondition(game.players, game.tactic.assignments), accruePressing(match.pressingExposure, game.tactic.pressing, match.minute))}</small></label><p className="analysis-hint"><Target /> Cel „Analiza”: najpierw trening analizy rywala, potem decyzja lub korekta po 30. minucie. Wynik meczu nie blokuje postępu.</p><div className="match-stats"><h3>Statystyki</h3><Stat label="Posiadanie" home={`${match.possessionHome}%`} away={`${100 - match.possessionHome}%`} /><Stat label="Strzały" home={String(visibleEvents.filter(e => e.side === "home" && ["goal","chance"].includes(e.kind)).length)} away={String(visibleEvents.filter(e => e.side === "away" && ["goal","chance"].includes(e.kind)).length)} /><Stat label="Żółte kartki" home={String(visibleEvents.filter((event) => event.side === "home" && event.kind === "card").length)} away={String(visibleEvents.filter((event) => event.side === "away" && event.kind === "card").length)} /></div><p className="consequence-note"><CircleAlert /> W meczu pojawi się {match.coachMoments?.length ?? 2} sytuacji decyzyjnych. Ich liczba rośnie wraz ze stawką.</p></aside></div>
  </div>;
}

function Stat({ label, home, away }: { label: string; home: string; away: string }) { return <div><b>{home}</b><span>{label}</span><b>{away}</b></div>; }

export function TableScreen({ game }: { game: GameState }) {
  const table = sortedTable(game.teams); const recent = game.fixtures.filter((fixture) => fixture.played).slice(-10).reverse();
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">{game.club.competition} • {game.club.group}</p><h1>Tabela i terminarz</h1><p>Tabela jest liczona wyłącznie z rozegranych spotkań.</p></div><Badge variant="outline">Sezon {game.season}</Badge></section><div className="table-layout"><section className="panel league-table"><div className="table-head"><span>#</span><span>Drużyna</span><span>M</span><span>W</span><span>R</span><span>P</span><span>BR</span><span>PKT</span></div>{table.map((team, index) => <div className={`table-row ${team.id === game.club.id ? "user-team" : ""}`} key={team.id}><b>{index + 1}</b><span><span className="tiny-crest">{initials(team.name).slice(0, 2)}</span><strong>{team.name}</strong></span><span>{team.played}</span><span>{team.won}</span><span>{team.drawn}</span><span>{team.lost}</span><span>{team.gf}:{team.ga}</span><b>{team.points}</b></div>)}</section><aside className="panel results"><div className="panel-title"><div><CalendarDays /><span>Ostatnie wyniki</span></div></div>{recent.length ? recent.map((fixture, index) => <div key={`${fixture.round}-${index}`}><small>K{fixture.round}</small><span>{teamForId(game, fixture.home)?.name}</span><b>{fixture.homeGoals}:{fixture.awayGoals}</b><span>{teamForId(game, fixture.away)?.name}</span></div>) : <div className="empty-state compact">Sezon jeszcze nie wystartował.</div>}</aside></div></div>;
}

export function TableScreenV14({ game }: { game: GameState }) {
  const table = sortedTable(game.teams); const recent = game.fixtures.filter((fixture) => fixture.played).slice(-8).reverse();
  const schedule = game.fixtures.filter((fixture) => fixture.home === game.club.id || fixture.away === game.club.id).sort((a, b) => a.round - b.round);
  const lastRound = Math.max(...game.fixtures.map((fixture) => fixture.round)); const winterAfter = Math.ceil(lastRound / 2);
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">{game.club.competition} • {game.club.group}</p><h1>Tabela i terminarz</h1><p>Jesień, przerwa zimowa i pełna runda wiosenna. Tabela nadal wynika wyłącznie z rozegranych spotkań.</p></div><Badge variant="outline">Sezon {game.season}</Badge></section><div className="table-layout"><section className="panel league-table"><div className="table-head"><span>#</span><span>Drużyna</span><span>M</span><span>W</span><span>R</span><span>P</span><span>BR</span><span>PKT</span></div>{table.map((team, index) => <div className={`table-row ${team.id === game.club.id ? "user-team" : ""}`} key={team.id}><b>{index + 1}</b><span><span className="tiny-crest">{initials(team.name).slice(0, 2)}</span><strong>{team.name}</strong></span><span>{team.played}</span><span>{team.won}</span><span>{team.drawn}</span><span>{team.lost}</span><span>{team.gf}:{team.ga}</span><b>{team.points}</b></div>)}</section><aside className="panel results"><div className="panel-title"><div><Trophy /><span>Ostatnie wyniki</span></div></div>{recent.length ? recent.map((fixture, index) => <div key={`${fixture.round}-${index}`}><small>K{fixture.round}</small><span>{teamForId(game, fixture.home)?.name}</span><b>{fixture.homeGoals}:{fixture.awayGoals}</b><span>{teamForId(game, fixture.away)?.name}</span></div>) : <div className="empty-state compact">Sezon jeszcze nie wystartował.</div>}</aside></div><section className="panel full-schedule"><div className="panel-title"><div><CalendarDays /><span>Terminarz {game.club.name}</span></div><small>{schedule.length} spotkań • daty ligowe</small></div><div className="schedule-list">{schedule.map((fixture) => { const home = fixture.home === game.club.id; const opponent = teamForId(game, home ? fixture.away : fixture.home); return <div key={`${fixture.round}-${fixture.home}-${fixture.away}`} className={`${fixture.round === game.round ? "current" : ""} ${fixture.played ? "played" : ""}`}><span className="schedule-date">{formatDate(fixture.date)}</span><b>K{fixture.round}</b><span className="venue">{home ? "DOM" : "WYJ."}</span><strong>{opponent?.name}</strong><em>{fixture.played ? `${home ? fixture.homeGoals : fixture.awayGoals}:${home ? fixture.awayGoals : fixture.homeGoals}` : "—"}</em></div>; })}</div>{schedule.some((fixture) => fixture.round === winterAfter) && <div className="winter-break"><span>PRZERWA ZIMOWA</span><b>{formatDate(schedule.find((fixture) => fixture.round === winterAfter)?.date ?? "")} → {formatDate(schedule.find((fixture) => fixture.round === winterAfter + 1)?.date ?? "")}</b></div>}</section><WorldOverview game={game} /></div>;
}

function WorldOverview({ game }: { game: GameState }) {
  const competitions = [...game.world.competitions].sort((a, b) => a.tier - b.tier || a.competition.localeCompare(b.competition, "pl") || a.group.localeCompare(b.group, "pl"));
  const groups = [...new Set(competitions.map((competition) => competition.competition))];
  const matches = competitions.reduce((sum, competition) => sum + competition.teams.reduce((teamSum, team) => teamSum + team.played, 0) / 2, 0);
  const managerChanges = competitions.reduce((sum, competition) => sum + competition.managerChanges, 0); const squadMoves = competitions.reduce((sum, competition) => sum + (competition.squadMoves ?? 0), 0);
  return <section className="world-competition-hub"><div className="world-hub-heading"><div><p className="eyebrow">ŻYWY ŚWIAT</p><h2>Polska gra również bez ciebie</h2><p>Każda liga rozgrywa własne kolejki zgodnie z datą kariery. Forma, morale, ruchy kadrowe, tabele i zmiany trenerów nie są zamrożone.</p></div><div><span><b>{competitions.length + 1}</b>rozgrywek</span><span><b>{Math.round(matches)}</b>meczów AI</span><span><b>{squadMoves}</b>ruchów kadrowych</span><span><b>{managerChanges}</b>zmian trenerów</span></div></div>{groups.map((competitionName) => { const items = competitions.filter((competition) => competition.competition === competitionName); return <details key={competitionName} open={["Ekstraklasa", "I liga", "II liga", "III liga"].includes(competitionName)}><summary><b>{competitionName}</b><span>{items.length} {items.length === 1 ? "grupa" : "grup"}</span></summary><div className="world-group-grid">{items.map((competition) => { const leader = sortedTable(competition.teams)[0]; const last = competition.lastResults[0]; return <article key={competition.id}><small>{competition.association}</small><strong>{competition.group}</strong><span>Kolejka {competition.currentRound}/{competition.totalRounds}</span><p><b>Lider:</b> {leader?.name ?? "—"} • {leader?.points ?? 0} pkt</p>{last && <em>{last.home} {last.homeGoals}:{last.awayGoals} {last.away}</em>}{competition.lastMarketEvent && <em>{competition.lastMarketEvent}</em>}</article>; })}</div></details>; })}</section>;
}

export function Career({ game, setGame }: { game: GameState; setGame: GameSetter }) {
  const target = nextLicense(game.coach.license); const course = target ? LICENSE_COURSES[target] : undefined; const tablePosition = sortedTable(game.teams).findIndex((team) => team.id === game.club.id) + 1;
  const startCourse = (funding: "self" | "club") => setGame(startLicenseCourse(game, funding));
  return <div className="page-stack"><section className="page-heading"><div><p className="eyebrow">PROFIL TRENERA</p><h1>{game.coach.name}</h1><p>{game.coach.age} lat • {game.coach.profile} • reputacja {game.coach.reputation}/100</p></div><Badge className="license-badge"><BadgeCheck /> {game.coach.license}</Badge></section><BoardGoalPanel game={game} /><div className="career-layout"><section className="panel license-course"><div className="panel-title"><div><BadgeCheck /><span>Licencje</span></div><small>mechanika czasu gry</small></div>{game.licenseCourse ? <><div className="course-progress"><span><b>Kurs {game.licenseCourse.target}</b><small>{game.licenseCourse.funding === "club" ? "finansuje klub" : "finansowanie własne"}</small></span><strong>{game.licenseCourse.weeksRemaining} tyg.</strong></div><Progress value={(1 - game.licenseCourse.weeksRemaining / game.licenseCourse.totalWeeks) * 100} /><p className="source-note">Postęp następuje raz po rozegranej kolejce. Kursu nie da się przyspieszyć klikaniem.</p></> : target && course ? <><h3>Następny krok: {target}</h3><p>Kurs trwa {course.weeks} tygodni meczowych. Koszt: {course.cost.toLocaleString("pl-PL")} zł. Licencja zwiększy dostępny poziom rynku pracy.</p><div className="course-actions"><Button variant="outline" onClick={() => startCourse("club")}>Poproś klub o finansowanie</Button><Button onClick={() => startCourse("self")}>Opłać sam</Button></div></> : <div className="empty-state compact"><BadgeCheck /><strong>Najwyższa licencja osiągnięta</strong></div>}{game.licenseMessage && <p className="course-message">{game.licenseMessage}</p>}<div className="funds-row"><span>Środki trenera</span><b>{game.finances.personalFunds.toLocaleString("pl-PL")} zł</b></div></section><section className="panel"><div className="panel-title"><div><Gauge /><span>Umiejętności</span></div><small>rozwój jest powolny</small></div><div className="skill-list">{Object.entries(game.coach.skills).map(([key, value]) => <div key={key}><span>{skillLabel(key)}</span><Progress value={value} /><b>{value}</b></div>)}</div></section><section className="panel"><div className="panel-title"><div><Shield /><span>{game.presidentName}</span></div><small>President AI</small></div><div className="president-grid">{Object.entries(game.president).map(([key, value]) => <div key={key}><span>{presidentLabel(key)}</span><b>{value}</b></div>)}</div><p className="source-note">Prezes pamięta wyniki, obietnice i konflikty. Cierpliwość nie jest losowana od nowa po każdym meczu.</p></section><section className="panel pressure-panel"><div className="panel-title"><div><Flame /><span>Presja i stres</span></div><small>wpływ pośredni</small></div>{Object.entries(game.pressures).map(([key, value]) => <div className="pressure-row" key={key}><span>{pressureName(key)}</span><Progress value={value} /><b>{value}%</b></div>)}</section><section className="panel history-panel"><div className="panel-title"><div><BriefcaseBusiness /><span>Historia kariery</span></div></div>{game.history.map((event, index) => <p key={index}>{event}</p>)}</section></div></div>;
}

export function Jobs({ game, acceptJob, stayAtClub }: { game: GameState; acceptJob: (offerId: string) => void; stayAtClub: () => void }) {
  const summer = Boolean(game.pendingSeason); const observations = game.jobOffers.filter((offer) => offer.stage === "obserwacja"); const offers = game.jobOffers.filter((offer) => offer.stage !== "obserwacja");
  return <div className="page-stack job-market-screen"><section className="page-heading"><div><p className="eyebrow">KARUZELA TRENERSKA</p><h1>Zainteresowanie ma sportowy powód</h1><p>Zimą widzisz zainteresowanie; formalne oferty i zmiana klubu są dostępne latem. Sytuacja sportowa klubu, twoja licencja, reputacja i ten sam ZPN wpływają na propozycje.</p></div><Badge className="license-badge">{game.coach.license}</Badge></section><section className="market-rules"><span><b>{game.worldActivity.managerChanges}</b> zmian trenerów łącznie w ostatnim obiegu świata — licznik nie wskazuje klubów</span><span><b>{game.coach.reputation}</b> reputacja</span><span><b>{summer ? "LATO" : observations.length ? "ZIMA" : "SEZON"}</b> etap rynku</span></section>
    {summer && <BoardGoalPanel game={game} />}
    {summer && game.employmentStatus === "employed" && <section className="panel stay-card"><div><small>OBECNY KONTRAKT</small><h2>{game.club.name}</h2><p>Po sezonie możesz zostać i wejść na poziom {game.pendingSeason?.targetTier}, albo przyjąć jedną z prawdziwych ofert.</p></div><Button onClick={stayAtClub}>Zostań w klubie <ChevronRight /></Button></section>}
    {!summer && game.employmentStatus === "employed" && <section className="panel market-status"><BriefcaseBusiness /><div><strong>Pracujesz w {game.club.name}</strong><p>{observations.length ? "Kluby poniżej obserwują twoją sytuację. To nie są jeszcze kontrakty — wynik rundy może zmienić ich zdanie." : "Brak zainteresowania pasującego do licencji i reputacji. Świat nadal rozgrywa mecze."}</p></div></section>}
    <section className="job-grid">{[...offers, ...observations].map((offer) => { const environment = environmentForTier(offer.tier); const observed = offer.stage === "obserwacja"; return <article className={`panel job-offer ${observed ? "observed" : ""}`} key={offer.id}><span>{observed ? "OBSERWACJA" : "FORMALNA OFERTA"} • dopasowanie {offer.fit ?? 50}%</span><h2>{offer.clubName}</h2><p>{offer.competition}. Projekt: {offer.expectation}.</p><p><b>Powód zainteresowania:</b> {offer.reason ?? "Starsza propozycja nie zawiera zapisanego powodu zainteresowania."}</p><p><b>Sytuacja sportowa:</b> {offer.situation ?? "Brak zapisanej sytuacji sportowej z chwili propozycji."}</p>{offer.sporting && <small>Stan na {formatDate(offer.sporting.asOf)} • sezon {offer.sporting.seasonYear}/{String(offer.sporting.seasonYear + 1).slice(-2)}</small>}<p><b>Dlaczego ty:</b> {offer.coachReason ?? "Starsza propozycja nie zawiera zapisanego uzasadnienia dopasowania."}</p><small>{environment.trainingSessions} sesji/tydz. • {environment.status} • ryzyko: {environment.risks[0]}</small>{summer && !observed && <Button onClick={() => acceptJob(offer.id)}>Przyjmij ofertę <ChevronRight /></Button>}</article>; })}</section>
    {!game.jobOffers.length && game.employmentStatus === "unemployed" && <section className="panel empty-state"><CircleAlert /><strong>Brak oferty spełniającej warunki</strong><span>Rynek nie gwarantuje pracy. Niższa reputacja, ograniczona licencja lub zły moment sezonu zawężają wybór.</span></section>}
  </div>;
}

function CareerV14Legacy({ game, setGame, retireCareer }: { game: GameState; setGame: GameSetter; retireCareer: () => void }) {
  const required = game.employmentStatus === "employed" ? game.club.tier <= 2 ? "UEFA PRO" : game.club.tier <= 5 ? "UEFA A" : game.club.tier <= 7 ? "UEFA B" : "Grassroots C" : game.coach.license;
  const covered = licenseCoversTier(game.coach.license, game.club.tier);
  return <div className="page-stack"><Career game={game} setGame={setGame} /><section className="panel career-summary"><div className="panel-title"><div><Trophy /><span>Bilans całej kariery</span></div><small>wszystkie zapisane sezony</small></div><div className="career-numbers"><span><b>{game.careerStats.seasons}</b>sezony</span><span><b>{game.careerStats.matches}</b>mecze</span><span><b>{game.careerStats.wins}</b>wygrane</span><span><b>{game.careerStats.promotions}</b>awanse</span><span><b>{game.careerStats.goalsCompleted}</b>cele</span><span><b>{game.careerStats.clubs.length}</b>kluby</span></div><p className="source-note">Najwyższy osiągnięty szczebel: {game.careerStats.highestTier}. Kluby: {game.careerStats.clubs.join(" → ")}.</p></section><section className="panel season-records"><div className="panel-title"><div><ClipboardList /><span>Sezony trenera</span></div></div>{game.seasonRecords.length ? [...game.seasonRecords].reverse().map((record) => <div key={`${record.season}-${record.club}`}><b>{record.season}</b><strong>{record.club}</strong><span>{record.place}. miejsce • {record.outcome}</span><small>{record.wins}W {record.draws}R {record.losses}P • cele trenera {record.goalsCompleted}/2</small>{record.boardGoal && <small>{boardGoalResultText(record.place, record.boardGoal.maxPlace, record.boardGoal.fulfilled)}</small>}</div>) : <div className="empty-state compact">Pierwszy sezon trwa.</div>}</section><section className={`panel license-compliance ${!covered ? "warning" : ""}`}><div className="panel-title"><div><BadgeCheck /><span>Wymóg aktualnego szczebla</span></div><small>{required}</small></div><p>{covered ? "Licencja spełnia wymaganie aktualnej ligi." : game.licenseCourse ? `Warunkowe dopuszczenie: trwa kurs ${game.licenseCourse.target}, pozostało ${game.licenseCourse.weeksRemaining} tygodni.` : `Aktualny poziom wymaga ${required}. Bez rozpoczęcia kursu kolejne oferty z tego szczebla będą zablokowane.`}</p></section>{game.coach.age >= 65 && !game.careerEnded && <section className="panel retirement-card"><div><BriefcaseBusiness /><strong>Masz {game.coach.age} lat. Decyzja należy wyłącznie do ciebie.</strong></div><p>Możesz grać dalej bez limitu albo zakończyć karierę i zamknąć kronikę. Gra nigdy nie kończy jej automatycznie.</p><Button variant="outline" onClick={retireCareer}>Zakończ karierę trenerską</Button></section>}{game.careerEnded && <section className="season-end hero-card"><div><BadgeCheck /><span>OSTATNI GWIZDEK</span></div><h2>{game.coach.name}</h2><p>{game.careerStats.matches} meczów, {game.careerStats.wins} zwycięstw, {game.careerStats.promotions} awansów i {game.careerStats.clubs.length} klubów.</p></section>}</div>;
}

export function CareerV14(props: { game: GameState; setGame: GameSetter; retireCareer: () => void }) {
  return <div className="page-stack career-archive-view"><CareerV14Legacy {...props} /><CareerArchive game={props.game} /></div>;
}

function CareerArchive({ game }: { game: GameState }) {
  const [filter, setFilter] = useState<"all" | "matches" | "decisions" | "courses">("all"); const [historyPage, setHistoryPage] = useState(0); const [seasonPage, setSeasonPage] = useState(0); const pageSize = 6;
  const filtered = game.history.filter((entry) => filter === "all" || (filter === "matches" && /\d+:\d+/.test(entry)) || (filter === "courses" && /kurs|licencj/i.test(entry)) || (filter === "decisions" && !/\d+:\d+|kurs|licencj/i.test(entry)));
  const historyPages = Math.max(1, Math.ceil(filtered.length / pageSize)); const safeHistoryPage = Math.min(historyPage, historyPages - 1); const seasonRecords = [...game.seasonRecords].reverse(); const seasonPages = Math.max(1, Math.ceil(seasonRecords.length / pageSize)); const safeSeasonPage = Math.min(seasonPage, seasonPages - 1);
  const chooseFilter = (next: typeof filter) => { setFilter(next); setHistoryPage(0); };
  return <section className="archive-console"><div className="archive-masthead"><div><p className="eyebrow">ARCHIWUM TRENERA</p><h2>Kronika bez kilometra przewijania</h2></div><span>{game.careerStats.seasons} sez. • {game.careerStats.matches} mecz.</span></div><div className="archive-tabs"><button className={filter === "all" ? "active" : ""} onClick={() => chooseFilter("all")}>Wszystko</button><button className={filter === "matches" ? "active" : ""} onClick={() => chooseFilter("matches")}>Mecze</button><button className={filter === "decisions" ? "active" : ""} onClick={() => chooseFilter("decisions")}>Decyzje</button><button className={filter === "courses" ? "active" : ""} onClick={() => chooseFilter("courses")}>Licencje</button></div><div className="archive-columns"><section className="panel archive-page"><div className="panel-title"><div><BriefcaseBusiness /><span>Ostatnie wydarzenia</span></div><small>{filtered.length} wpisów</small></div>{filtered.length ? filtered.slice(safeHistoryPage * pageSize, safeHistoryPage * pageSize + pageSize).map((event, index) => <p key={`${safeHistoryPage}-${index}`}>{event}</p>) : <div className="empty-state compact">Brak wpisów w tym dziale.</div>}<Pager page={safeHistoryPage} pages={historyPages} setPage={setHistoryPage} /></section><section className="panel archive-seasons"><div className="panel-title"><div><ClipboardList /><span>Sezony</span></div><small>{seasonRecords.length}</small></div>{seasonRecords.length ? seasonRecords.slice(safeSeasonPage * pageSize, safeSeasonPage * pageSize + pageSize).map((record) => <div key={`${record.season}-${record.club}`}><b>{record.season}</b><strong>{record.club}</strong><span>{record.place}. miejsce • {record.outcome}</span><small>{record.wins}W {record.draws}R {record.losses}P • cele trenera {record.goalsCompleted}/2</small>{record.boardGoal && <small>{boardGoalResultText(record.place, record.boardGoal.maxPlace, record.boardGoal.fulfilled)}</small>}</div>) : <div className="empty-state compact">Pierwszy sezon trwa.</div>}<Pager page={safeSeasonPage} pages={seasonPages} setPage={setSeasonPage} /></section></div></section>;
}

function Pager({ page, pages, setPage }: { page: number; pages: number; setPage: Dispatch<SetStateAction<number>> }) { return <nav className="archive-pager" aria-label="Strony archiwum"><button disabled={page <= 0} onClick={() => setPage((value) => Math.max(0, value - 1))}>‹ Nowsze</button><span>{page + 1} / {pages}</span><button disabled={page >= pages - 1} onClick={() => setPage((value) => Math.min(pages - 1, value + 1))}>Starsze ›</button></nav>; }

function initials(name: string) { return name.split(" ").filter(Boolean).map((word) => word[0]).join("").slice(0, 3).toUpperCase(); }
function signed(value: number) { return `${value >= 0 ? "+" : ""}${Number.isInteger(value) ? value : value.toFixed(1)}`; }
function burnoutLabel(value: number) { return value < 25 ? "niskie" : value < 45 ? "rosnące" : value < 65 ? "wysokie" : "krytyczne"; }
function dateDistance(from: string, to: string) { const start = new Date(`${from}T12:00:00Z`).getTime(); const end = new Date(`${to}T12:00:00Z`).getTime(); return Number.isFinite(start) && Number.isFinite(end) ? Math.max(2, Math.round((end - start) / 86400000)) : 7; }
